package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Columns  []string `json:"columns"`
	OrderBy  string   `json:"order_by"`
	Limit    int      `json:"limit"`
}

type SearchResult struct {
	Rows []map[string]interface{} `json:"rows"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	// Set search_path to restrict schema access
	db.Exec("SET search_path TO public")
}

// sanitizeIdentifier attempts to prevent injection in identifiers
func sanitizeIdentifier(s string) string {
	// Remove obvious dangerous characters but allow dots for schema.table
	s = strings.ReplaceAll(s, ";", "")
	s = strings.ReplaceAll(s, "--", "")
	s = strings.ReplaceAll(s, "/*", "")
	return s
}

func validateColumns(cols []string) []string {
	allowed := map[string]bool{
		"id": true, "title": true, "description": true,
		"category": true, "created_at": true, "author": true,
		"status": true, "priority": true,
	}
	var valid []string
	for _, c := range cols {
		if allowed[strings.ToLower(strings.TrimSpace(c))] {
			valid = append(valid, c)
		}
	}
	if len(valid) == 0 {
		return []string{"id", "title"}
	}
	return valid
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if req.Limit <= 0 || req.Limit > 100 {
		req.Limit = 20
	}

	validCols := validateColumns(req.Columns)
	colList := strings.Join(validCols, ", ")

	// ORDER BY is user-controlled - sanitizeIdentifier is insufficient
	orderClause := ""
	if req.OrderBy != "" {
		orderClause = fmt.Sprintf(" ORDER BY %s", sanitizeIdentifier(req.OrderBy))
	}

	// Query uses parameterized WHERE but injectable ORDER BY
	query := fmt.Sprintf(
		"SELECT %s FROM tickets WHERE (title ILIKE $1 OR description ILIKE $1) AND status != 'deleted'%s LIMIT %d",
		colList, orderClause, req.Limit,
	)

	searchPattern := "%" + req.Query + "%"
	rows, err := db.Query(query, searchPattern)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	columns, _ := rows.Columns()
	var results []map[string]interface{}

	for rows.Next() {
		values := make([]interface{}, len(columns))
		pointers := make([]interface{}, len(columns))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range columns {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(SearchResult{Rows: results})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
